fn map_list(comptime T37: type, comptime T38: type, f: CxFn1(T37, T38), xs: *CxList(T37)) *CxList(T38) {
    return map_list_loop(T37, T38, f, xs, 0, cx_list_len(xs), cx_ll_empty(T38));
}

fn map_list_loop(comptime T39: type, comptime T40: type, f: CxFn1(T39, T40), xs: *CxList(T39), i_: i64, len_: i64, acc_: *CxList(T40)) *CxList(T40) {
    var _tl_i = i_;
    var _tl_acc = acc_;
    while (true) {
        if ((_tl_i == len_)) { return _tl_acc; } else { { const _tj1_2 = (_tl_i + 1); const _tj1_4 = cx_ll_push(_tl_acc, f.call(f.ctx, cx_list_at(xs, _tl_i))); _tl_i = _tj1_2; _tl_acc = _tj1_4; continue; } }
    }
}

