fn eg_id(c_: EgCatalog, id: i64) bool {
    return ((id > 0) and (id <= cx_list_len(c_.items)));
}

fn eg_optional(c_: EgCatalog, id: i64) bool {
    return ((id == 0) or eg_id(c_, id));
}

fn eg_pair(c_: EgCatalog, id: i64, quantity: i64) bool {
    return (((id == 0) and (quantity == 0)) or ((eg_id(c_, id) and (quantity > 0)) and (quantity <= 1000)));
}

fn eg_items_valid(c_: EgCatalog, i_: i64) bool {
    return (if ((i_ == cx_list_len(c_.items))) true else b1: { const item = cx_list_at(c_.items, i_); break :b1 (((((cx_text_len(item.name) > 0) and (cx_text_len(item.name) <= 64)) and (item.chain >= 1)) and (item.chain <= 7)) and eg_items_valid(c_, (i_ + 1))); });
}

fn eg_resources_valid(c_: EgCatalog, i_: i64) bool {
    return (if ((i_ == cx_list_len(c_.resources))) true else b1: { const r_ = cx_list_at(c_.resources, i_); break :b1 (((((((((((((eg_id(c_, r_.item) and eg_optional(c_, r_.seed)) and eg_optional(c_, r_.tool)) and (r_.item != r_.seed)) and (r_.skill >= 0)) and (r_.skill <= 10)) and (r_.ground >= 0)) and (r_.ground <= 2)) and (((r_.seed == 0) and (r_.ground == 0)) or ((r_.seed > 0) and (r_.ground > 0)))) and (r_.regrow > 0)) and (r_.regrow <= 8760)) and (r_.quantity > 0)) and (r_.quantity <= 1000)) and eg_resources_valid(c_, (i_ + 1))); });
}

fn eg_recipes_valid(c_: EgCatalog, i_: i64) bool {
    return (if ((i_ == cx_list_len(c_.recipes))) true else b1: { const r_ = cx_list_at(c_.recipes, i_); break :b1 ((((((((((((((eg_id(c_, r_.item) and (r_.quantity > 0)) and (r_.quantity <= 1000)) and eg_id(c_, r_.one)) and eg_pair(c_, r_.one, r_.one_count)) and eg_pair(c_, r_.two, r_.two_count)) and eg_pair(c_, r_.three, r_.three_count)) and ((r_.two == 0) or (r_.one != r_.two))) and ((r_.three == 0) or ((r_.three != r_.one) and (r_.three != r_.two)))) and eg_optional(c_, r_.tool)) and (r_.station >= 1)) and (r_.station <= 24)) and (r_.skill >= 0)) and (r_.skill <= 11)) and eg_recipes_valid(c_, (i_ + 1))); });
