/// ASCII as the chapter's text holds it (CCE): each byte the code whose
/// code point it is, by the runtime's own table; a byte that is no ASCII,
/// or ASCII the table does not hold, is refused.
fn asciiToCce(s: []const u8) error{NotAscii}![]const u8 {
    const out = cx_raw(u8, s.len);
    for (s, 0..) |c, i| out[i] = ascii_to_cce[c] orelse return error.NotAscii;
    return out;
}

const ascii_to_cce: [256]?u8 = blk: {
    var t: [256]?u8 = @splat(null);
    for (cce_table, 0..) |cp, code| {
        if (cp < 128 and t[cp] == null) t[cp] = @intCast(code);
    }
    break :blk t;
};
